-- =====================================================
-- MovieLens 1M -> 电商商品数据转换脚本
-- 数据来源: MovieLens 1M (movies.dat)
-- 说明: 将电影数据包装为电商商品数据
-- =====================================================

SET FOREIGN_KEY_CHECKS=0;
SET NAMES utf8mb4;

TRUNCATE TABLE items;


ALTER TABLE items AUTO_INCREMENT = 4883;

SET FOREIGN_KEY_CHECKS=1;

SELECT COUNT(*) AS total_items FROM items;

-- 共生成 3883 条商品数据